    title: "סקיל AZURE AI PIPELINE: מקובץ לרשומה מסודרת, בלי רישיונות פרימיום",
    excerpt: "סקיל ל-Claude Code שמלווה בניית צינור ב-Azure: קובץ נכנס לתיקייה, מודל מחזיר JSON מובנה, ונוצרות רשומה ומייל. בלי רישיונות פרימיום, ועם 14 הכשלים שקרו לי בדרך ואיך מזהים כל אחד מהם.",
    content: `<p>רוצים שקובץ שנכנס לתיקייה ייקרא על ידי מודל, יחזור כנתונים מסודרים, ייכנס לרשימה וישלח מייל, בארגון שיש לו Microsoft 365 Business Standard ואין לו רישיונות פרימיום?</p>

<p>🎯 הסקיל השבוע: <strong>AZURE AI PIPELINE</strong></p>

<p>בניתי את הצינור הזה מקצה לקצה ביום אחד. הוא נכשל 14 פעמים בדרך. הסקיל הוא מה שהייתי רוצה לקרוא לפני שהתחלתי: באיזה סדר לבנות, ובאיזה מקום בדיוק זה נשבר.</p>

<p><strong>למה Logic Apps ולא Power Automate?</strong></p>

<p>כדי לקרוא למודל מתוך Power Automate צריך את מחבר ה-HTTP, שהוא מחבר פרימיום ואינו זמין ברישיון Business Standard. Logic Apps בתצורת Consumption מחויב לפי כל פעולה שרצה, מתוך מנוי Azure, בלי רישיון למשתמש. הסקיל אומר גם את המחיר של הבחירה: הזרימה יושבת מחוץ לשכבת הממשל של Power Platform, מי שמתחזק אותה צריך להכיר Logic Apps, והחיוב לפי פעולה עלול להתהפך בנפח גדול.</p>

<p><strong>הכשלים שעלו לי הכי הרבה זמן היו השקטים:</strong></p>

<ul>
<li>🗓️ סיכום מושלם, בשפה רהוטה, עם תאריכים וסטטוסים שאף אחד לא כתב במסמך</li>
<li>📭 מייל שיצא עם גוף ריק לאורך שבוע של ריצות, וכל ריצה סומנה כהצלחה</li>
<li>🔁 תיקון שהשרת קיבל, והריצה הבאה לא השתמשה בו</li>
</ul>

<p>חמישה כשלים נוספים התבררו בסוף ככשל אחד: הצינור ניחש את צורת הפלט של המודל, ושמות השדות השתנו בין ריצה לריצה. הפתרון היה סכימה קשיחה (json_schema עם strict), יחד עם כלל בפרומפט: שדה בלי מקור מפורש במסמך מקבל "לא צוין".</p>

<p><strong>עוד מלכודות שמתועדות בסקיל:</strong></p>

<ul>
<li>מגבלת טוקנים לדקה היא מגבלת קצב. הורדה שלה למינימום כדי לחסוך רק חוסמת: מסמך של 8,000 טוקנים מול מגבלה של 1K מחזיר 429</li>
<li>התראות תקציב מתריעות. הן לא עוצרות הוצאה</li>
<li>קובץ מ-SharePoint מגיע כ-base64, וצריך להמיר אותו לטקסט לפני ששולחים אותו למודל</li>
<li>במקום מפתח API בתוך הזרימה, זהות מנוהלת (Managed Identity) עם הרשאה למשאב המודל</li>
<li>משך הכשל הוא אבחנה: כשל בשבריר שנייה לא יצא מהמכונה, ואין טעם לחפש במפתחות</li>
</ul>

<p>✅ <strong>מתי תיקון נחשב מאומת?</strong> כששלושה תנאים מתקיימים יחד: חיפוש שמצא את כל המקומות עם אותה תבנית, ריצה חדשה שהופעלה מקובץ חדש, וכל הפעולות בריצה הסתיימו ב-Succeeded.</p>

<p>מתאים למי שבונה אוטומציה עם מודל בתוך ארגון, ומעביר קובץ כדי לקבל ממנו נתונים מובנים שאנשים אמיתיים מסתכלים בהם. אין בסקיל קוד להעתקה ואין תבנית מוכנה. יש בו סדר בנייה ומלכודות, כי הצינור שלכם יהיה שונה משלי.</p>

<p><strong>התקנה:</strong> מורידים את SKILL.md מהריפו לתיקייה ~/.claude/skills/azure-ai-pipeline. הקובץ הוא טקסט, והוא עובד גם ב-Codex ובכלים אחרים שקוראים קבצי הנחיות.</p>

<p><a href="https://github.com/guycoful/azure-ai-pipeline-skill" target="_blank" rel="noopener noreferrer" class="inline-block bg-purple-600 hover:bg-purple-700 text-white font-bold py-3 px-6 rounded-lg transition-colors text-center">לריפו המלא בגיטהאב</a></p>`,
    date: "2026-08-05",
    readingTime: 2,
    tags: ["Claude Code", "סקילים", "Azure", "Logic Apps", "אוטומציה"],
    category: "skills",
    image: "/images/articles/skill-azure-ai-pipeline.jpg",
